mapper.select:
SELECT /* com.kt.openapi.web.api.dao.ApiInfoDAO.selApiSearchList */ BB.*, ROW_NUMBER() OVER (ORDER BY LOWER(BB.API_NM)) rownum FROM ( SELECT A.API_SPC_NO ,A.API_SPC_ID ,A.VER ,A.API_NM ,A.API_DESC AS API_SPC_DESC ,A.AUT_ID ,A.SYS_ID ,C.SYS_NM ,A.VER_DESC ,A.RFRN_WSDL_URL ,A.RFRN_TMPLT_NO ,A.RFRN_API_SPC_NO ,A.HOST ,A.BAS_PATH ,A.YAML_FILE_PATH ,A.YAML_FILE_NM ,A.REG_STTUS_CD ,A.TMPLT_YN ,A.REG_APVR ,A.REG_DT ,COALESCE(A.REGR,'') AS REGR ,A.AMD_DT ,COALESCE(A.AMDR,'') AS AMDR ,A.DEL_YN ,A.DEL_DT ,COALESCE(A.DELR,'') AS DELR ,A.YAML_SBST ,A.SHOW_YN ,B.API_NM AS TITLE_NM ,B.API_NO AS API_NO ,B.API_ID AS API_ID ,B.API_PATH AS API_PATH ,B.API_DESC AS API_DESC ,B.SORT_ODRG ,COALESCE(D.CD_NM,'') AS METHOD FROM (
) A INNER JOIN KOA_TB_API_DEF B ON A.API_SPC_NO = B.API_SPC_NO LEFT OUTER JOIN KOA_TB_API_SYSTEM C ON A.SYS_ID = C.SYS_ID LEFT OUTER JOIN KOA_TB_COMN_CD D ON (B.METHOD_CD = D.COMN_CD) WHERE 1=1 AND A.SYS_ID NOT IN ('SHUB','AUTHENTI','INFRA','APPLICATI')
AND (UPPER(B.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') OR UPPER(B.API_DESC) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') )
UNION ALL
SELECT A.API_SPC_NO ,A.API_SPC_ID ,A.VER ,A.API_NM ,A.API_DESC AS API_SPC_DESC ,A.AUT_ID ,A.SYS_ID ,C.SYS_NM ,A.VER_DESC ,A.RFRN_WSDL_URL ,A.RFRN_TMPLT_NO ,A.RFRN_API_SPC_NO ,A.HOST ,A.BAS_PATH ,A.YAML_FILE_PATH ,A.YAML_FILE_NM ,A.REG_STTUS_CD ,A.TMPLT_YN ,A.REG_APVR ,A.REG_DT ,COALESCE(A.REGR,'') AS REGR ,A.AMD_DT ,COALESCE(A.AMDR,'') AS AMDR ,A.DEL_YN ,A.DEL_DT ,COALESCE(A.DELR,'') AS DELR ,A.YAML_SBST ,A.SHOW_YN ,B.API_NM AS TITLE_NM ,B.API_NO AS API_NO ,B.API_ID AS API_ID ,B.API_PATH AS API_PATH ,B.API_DESC AS API_DESC ,B.SORT_ODRG ,COALESCE(D.CD_NM,'') AS METHOD FROM (
) A INNER JOIN KOA_TB_API_DEF B ON A.API_SPC_NO = B.API_SPC_NO LEFT OUTER JOIN KOA_TB_API_SYSTEM C ON A.SYS_ID = C.SYS_ID LEFT OUTER JOIN KOA_TB_COMN_CD D ON (B.METHOD_CD = D.COMN_CD) WHERE 1=1 AND A.RN = 1 AND A.SYS_ID IN ('SHUB','AUTHENTI','INFRA','APPLICATI')
AND (UPPER(B.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') OR UPPER(B.API_DESC) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') )
) BB WHERE 1=1

SELECT /* com.kt.openapi.web.api.dao.ApiInfoDAO.selApiSearchCnt */ SUM(AA.cnt) FROM ( SELECT COUNT(*) AS cnt FROM (
) A INNER JOIN KOA_TB_API_DEF B ON A.API_SPC_NO = B.API_SPC_NO LEFT OUTER JOIN KOA_TB_API_SYSTEM C ON A.SYS_ID = C.SYS_ID WHERE A.SYS_ID NOT IN ('SHUB','AUTHENTI','INFRA','APPLICATI')
AND (UPPER(B.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') OR UPPER(B.API_DESC) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') )
UNION ALL
SELECT COUNT(*) AS cnt FROM (
) A INNER JOIN KOA_TB_API_DEF B ON A.API_SPC_NO = B.API_SPC_NO LEFT OUTER JOIN KOA_TB_API_SYSTEM C ON A.SYS_ID = C.SYS_ID WHERE A.RN = 1 AND A.SYS_ID IN ('SHUB','AUTHENTI','INFRA','APPLICATI')
AND (UPPER(B.API_NM) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') OR UPPER(B.API_DESC) LIKE CONCAT('%' , UPPER(#{searchKeyword}) , '%') )
) AA
